// CSV exporter.
// Checks permission, builds CSV with header, records audit.

import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('Permission denied');
  }

  const tasks = Array.from(taskManager.listAll());

  const escape = (val: string) => {
    if (val.includes(',') || val.includes('"') || val.includes('\n')) {
      return `"${val.replace(/"/g, '""')}"`;
    }
    return val;
  };

  const header = 'id,title,status,assignee,createdAt';
  const rows = tasks.map((t) =>
    [t.id, t.title, t.status, t.assignee, String(t.createdAt)]
      .map(escape)
      .join(','),
  );

  const csv = [header, ...rows].join('\n');

  record({
    action: 'export',
    userId,
    timestamp: Date.now(),
  });

  return csv;
}

